def hook(ctx, nb):
    if ctx['action']['tool'] != 'click_action':
        return None
    val = ctx['action']['value_normalized']
    if val != 'buy now':
        return None
    if ctx['predicates']['product_price_over_budget']:
        return {'kind': 'block_and_prompt', 'message': 'Do not buy this item: its current price is over the stated budget. Go back to search/results and choose an in-budget product.'}
    if ctx['predicates']['required_options_unselected']:
        return {'kind': 'block_and_prompt', 'message': 'Do not buy yet: a required product option from the instruction is still unselected. Choose the matching visible color, size, material, flavor, count, or style first; if no matching option is visible, use Back to Search.'}
    return None
